    address cid,
    uint256 newJailedUntil,
    uint256 slashAmount,
    bool cannotBailout
  ) external;

  /**
   * @dev Finalize the bailout request from slash indicator contract.
   *
   * Requirements:
   * - The method caller is slash indicator contract.
   *
   * Emits the event `ValidatorUnjailed`.
   *
   */
  function execBailOut(
    address cid,
    uint256 period
  ) external;
}

