// SPDX-License-Identifier: MIT

pragma solidity ^0.8.9;

import "../../interfaces/staking/IRewardPool.sol";
import "../../libraries/Math.sol";
import { TPoolId } from "../../udvts/Types.sol";

/**
 * @title RewardCalculation contract
 * @dev This contract mainly contains the methods to calculate reward for staking contract.
 */
abstract contract RewardCalculation is IRewardPool {
  /// @dev Mapping from pool address => period number => accumulated rewards per share (one unit staking)
  mapping(address poolId => mapping(uint256 periodNumber => PeriodWrapper)) private _accumulatedRps;
  /// @dev Mapping from the pool address => user address => the reward info of the user
  mapping(address poolId => mapping(address user => UserRewardFields)) private _userReward;
  /// @dev Mapping from the pool address => reward pool fields
  mapping(address poolId => PoolFields) private _stakingPool;

  /**
   * @dev This empty reserved space is put in place to allow future versions to add new
   * variables without shifting down storage in the inheritance chain.
   */
  uint256[50] private ______gap;

  /**
   * @inheritdoc IRewardPool
   */
  function getReward(
    TConsensus consensusAddr,
    address user
  ) external view returns (uint256) {
    address poolId = __css2cid(consensusAddr);
    return getRewardById(poolId, user);
  }

  /**
   * @inheritdoc IRewardPool
   */
  function getRewardById(
    address poolId,
    address user
  ) public view returns (uint256) {
    return _getReward(poolId, user, _currentPeriod(), _getStakingAmount(poolId, user));
  }

  /**
   * @dev See {IRewardPool-getStakingAmount}
   */
  function _getStakingAmount(
    address poolId,
    address user
  ) internal view virtual returns (uint256);

  /**
   * @dev See {IRewardPool-getStakingTotal}
   */
  function _getStakingTotal(
    address poolId
  ) internal view virtual returns (uint256);

  /**
   * @dev Returns the reward amount that user claimable.
   */
  function _getReward(
    address poolId,
    address user,
    uint256 latestPeriod,
    uint256 latestStakingAmount
  ) internal view returns (uint256) {
    UserRewardFields storage _reward = _userReward[poolId][user];

    if (_reward.lastPeriod == latestPeriod) {
      return _reward.debited;
    }

    uint256 aRps;
    uint256 lastPeriodReward;
    PoolFields storage _pool = _stakingPool[poolId];
    PeriodWrapper storage _wrappedArps = _accumulatedRps[poolId][_reward.lastPeriod];

    if (_wrappedArps.lastPeriod > 0) {
      // Calculates the last period reward if the aRps at the period is set
      aRps = _wrappedArps.inner;
      lastPeriodReward = _reward.lowestAmount * (aRps - _reward.aRps);
    } else {
      // Fallbacks to the previous aRps in case the aRps is not set
      aRps = _reward.aRps;
    }

    uint256 newPeriodsReward = latestStakingAmount * (_pool.aRps - aRps);
    return _reward.debited + (lastPeriodReward + newPeriodsReward) / 1e18;
  }

  /**
   * @dev Syncs the user reward.
   *
   * Emits the event `UserRewardUpdated` once the debit amount is updated.
   * Emits the event `PoolSharesUpdated` once the pool share is updated.
   *
   * Note: The method should be called whenever the user's staking amount changes.
   *
   */
  function _syncUserReward(
    address poolId,
    address user,
    uint256 newStakingAmount
  ) internal {
    uint256 period = _currentPeriod();
    PoolFields storage _pool = _stakingPool[poolId];
    uint256 lastShares = _pool.shares.inner;

    // Updates the pool shares if it is outdated
    if (_pool.shares.lastPeriod < period) {
      _pool.shares = PeriodWrapper(_getStakingTotal(poolId), period);
    }

    UserRewardFields storage _reward = _userReward[poolId][user];
    uint256 currentStakingAmount = _getStakingAmount(poolId, user);
    uint256 debited = _getReward(poolId, user, period, currentStakingAmount);

    if (_reward.debited != debited) {
      _reward.debited = debited;
      emit UserRewardUpdated(poolId, user, debited);
    }

    _syncMinStakingAmount(_pool, _reward, period, newStakingAmount, currentStakingAmount);
    _reward.aRps = _pool.aRps;
    _reward.lastPeriod = period;

    if (_pool.shares.inner != lastShares) {
      emit PoolSharesUpdated(period, poolId, _pool.shares.inner);
    }
  }

  /**
   * @dev Syncs the minimum staking amount of an user in the current period.
   */
  function _syncMinStakingAmount(
    PoolFields storage _pool,
    UserRewardFields storage _reward,
    uint256 latestPeriod,
    uint256 newStakingAmount,
    uint256 currentStakingAmount
  ) internal {
    if (_reward.lastPeriod < latestPeriod) {
      _reward.lowestAmount = currentStakingAmount;
    }

    uint256 lowestAmount = Math.min(_reward.lowestAmount, newStakingAmount);
    uint256 diffAmount = _reward.lowestAmount - lowestAmount;
    if (diffAmount > 0) {
      _reward.lowestAmount = lowestAmount;
      if (_pool.shares.inner < diffAmount) revert ErrInvalidPoolShare();
      _pool.shares.inner -= diffAmount;
    }
  }

  /**
   * @dev Claims the settled reward for a specific user.
   *
   * @param lastPeriod Must be in two possible value: `_currentPeriod` in normal calculation, or
   * `_currentPeriod + 1` in case of calculating the reward for revoked validators.
   *
   * Emits the `RewardClaimed` event and the `UserRewardUpdated` event.
   *
   * Note: This method should be called before transferring rewards for the user.
   *
   */
  function _claimReward(
    address poolId,
    address user,
    uint256 lastPeriod
  ) internal returns (uint256 amount) {
    uint256 currentStakingAmount = _getStakingAmount(poolId, user);
    amount = _getReward(poolId, user, lastPeriod, currentStakingAmount);
    emit RewardClaimed(poolId, user, amount);

    UserRewardFields storage _reward = _userReward[poolId][user];
    _reward.debited = 0;
    _syncMinStakingAmount(_stakingPool[poolId], _reward, lastPeriod, currentStakingAmount, currentStakingAmount);
    _reward.lastPeriod = lastPeriod;
    _reward.aRps = _stakingPool[poolId].aRps;
    emit UserRewardUpdated(poolId, user, 0);
  }

  /**
   * @dev Records the amount of rewards `_rewards` for the pools `poolIds`.
   *
   * Emits the event `PoolsUpdated` once the contract recorded the rewards successfully.
   * Emits the event `PoolsUpdateFailed` once the input array lengths are not equal.
   * Emits the event `PoolUpdateConflicted` when the pool is already updated in the period.
   *
   * Note: This method should be called once at the period ending.
   *
   */
  function _recordRewards(
    address[] memory poolIds,
    uint256[] calldata rewards,
    uint256 period
  ) internal {
    if (poolIds.length != rewards.length) {
      emit PoolsUpdateFailed(period, poolIds, rewards);
      return;
    }

    uint256 rps;
    uint256 count;
    address poolId;
    uint256 stakingTotal;
    uint256[] memory aRps = new uint256[](poolIds.length);
    uint256[] memory shares = new uint256[](poolIds.length);
    address[] memory conflicted = new address[](poolIds.length);

    for (uint256 i = 0; i < poolIds.length; i++) {
      poolId = poolIds[i];
      PoolFields storage _pool = _stakingPool[poolId];
      stakingTotal = _getStakingTotal(poolId);

      if (_accumulatedRps[poolId][period].lastPeriod == period) {
        unchecked {
          conflicted[count++] = poolId;
        }
        continue;
      }

      // Updates the pool shares if it is outdated
      if (_pool.shares.lastPeriod < period) {
        _pool.shares = PeriodWrapper(stakingTotal, period);
      }

      // The rps is 0 if no one stakes for the pool
      rps = _pool.shares.inner == 0 ? 0 : (rewards[i] * 1e18) / _pool.shares.inner;
      aRps[i - count] = _pool.aRps += rps;
      _accumulatedRps[poolId][period] = PeriodWrapper(_pool.aRps, period);
      _pool.shares.inner = stakingTotal;
      shares[i - count] = _pool.shares.inner;
      poolIds[i - count] = poolId;
    }

    if (count > 0) {
      assembly {
        mstore(conflicted, count)
        mstore(poolIds, sub(mload(poolIds), count))
      }
      emit PoolsUpdateConflicted(period, conflicted);
    }

    if (poolIds.length > 0) {
      emit PoolsUpdated(period, poolIds, aRps, shares);
    }
  }

  /**
   * @dev Returns the current period.
   */
  function _currentPeriod() internal view virtual returns (uint256);

  function __css2cid(
    TConsensus consensusAddr
  ) internal view virtual returns (address);
}

src/ronin/staking/Staking.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.9;

import "../../interfaces/staking/IStaking.sol";
import "../../interfaces/validator/IRoninValidatorSet.sol";
import "../../libraries/Math.sol";
import "../../utils/CommonErrors.sol";
import "./StakingCallback.sol";
import "@openzeppelin-v4/contracts/access/AccessControlEnumerable.sol";
import "@openzeppelin-v4/contracts/proxy/utils/Initializable.sol";

contract Staking is IStaking, StakingCallback, Initializable, AccessControlEnumerable {
  bytes32 public constant MIGRATOR_ROLE = keccak256("MIGRATOR_ROLE");
  bytes32 public constant L2_MIGRATOR_ROLE = keccak256("L2_MIGRATOR_ROLE");

  // keccak256(abi.encode(uint256(keccak256("ronin.storage.StakingRep4MigratedStorageLocation")) - 1)) & ~bytes32(uint256(0xff))
  bytes32 private constant $_StakingRep4MigratedStorageLocation =
    0x02b7258856b9f6bdff23dae2002215e15e9b3a0101a83005baf0725f1e37df00;

  /// @notice Flag indicating whether the contract has been migrated to L2.
  bool internal s_l2Migrated;

  error ErrL2MigrationNotCompleted();
  error ErrPoolRevokingTimestampNotReach(address poolId, uint256 revokingTimestamp, uint256 blockTimestamp);

  event L2MigrationStatusUpdated(address indexed by, bool status);
  event PoolDeprecated(address indexed poolId);

  modifier onRep4Migration() {
    uint256 val;
    assembly ("memory-safe") {
      val := sload($_StakingRep4MigratedStorageLocation)
    }

    if (val > 0) revert ErrMigrateWasAdminAlreadyDone();
    _;
  }

  modifier onlyL2Migrated() {
    require(s_l2Migrated, ErrL2MigrationNotCompleted());
    _;
  }

  constructor() {
    _disableInitializers();
  }

  receive() external payable onlyContract(ContractType.VALIDATOR) { }

  fallback() external payable onlyContract(ContractType.VALIDATOR) { }

  /**
   * @dev Initializes the contract storage.
   */
  function initialize(
    address __validatorContract,
    uint256 __minValidatorStakingAmount,
    uint256 __maxCommissionRate,
    uint256 __cooldownSecsToUndelegate,
    uint256 __waitingSecsToRevoke
  ) external initializer {
    _setContract(ContractType.VALIDATOR, __validatorContract);
    _setMinValidatorStakingAmount(__minValidatorStakingAmount);
    _setCommissionRateRange(0, __maxCommissionRate);
    _setCooldownSecsToUndelegate(__cooldownSecsToUndelegate);
    _setWaitingSecsToRevoke(__waitingSecsToRevoke);
  }

  /**
   * @dev Initializes the contract storage V2.
   */
  function initializeV2() external reinitializer(2) {
    _setContract(ContractType.VALIDATOR, ______deprecatedValidator);
    delete ______deprecatedValidator;
  }

  /**
   * @dev Initializes the contract storage V3.
   */
  function initializeV3(
    address __profileContract
  ) external reinitializer(3) {
    _setContract(ContractType.PROFILE, __profileContract);
  }

  function initializeV4(
    address admin,
    address migrator
  ) external reinitializer(4) {
    _grantRole(DEFAULT_ADMIN_ROLE, admin);
    _grantRole(MIGRATOR_ROLE, migrator);
  }

  function initializeV5(
    address migrator
  ) external reinitializer(5) {
    _grantRole(L2_MIGRATOR_ROLE, migrator);
  }

  function setL2Migrated(
    bool status
  ) external onlyRole(L2_MIGRATOR_ROLE) {
    s_l2Migrated = status;
    emit L2MigrationStatusUpdated(msg.sender, status);
  }

  function isL2Migrated() external view returns (bool) {
    return s_l2Migrated;
  }

  /// @dev Returns whether trusted organizations should be allowed to renounce.
  /// After L2 migration, trusted orgs need the ability to exit gracefully.
  function _shouldAllowTrustedOrg() internal view virtual override returns (bool) {
    return s_l2Migrated;
  }

  function execRenounceAndDeprecatePool(
    address poolId
  ) external onlyPoolAdmin(_poolDetail[poolId], msg.sender) onlyL2Migrated {
    IRoninValidatorSet validatorContract = IRoninValidatorSet(getContract(ContractType.VALIDATOR));
    uint256 revokingTimestamp = validatorContract.getCandidateInfoById(poolId).revokingTimestamp;
    uint256 currentPeriod = validatorContract.currentPeriod();

    require(
      revokingTimestamp != 0 && revokingTimestamp < block.timestamp,
      ErrPoolRevokingTimestampNotReach(poolId, revokingTimestamp, block.timestamp)
    );

    _deprecatePool(poolId, currentPeriod);

    emit PoolDeprecated(poolId);
  }

  /**
   * @dev Migrate REP-4
   */
  function migrateWasAdmin(
    address[] calldata poolIds,
    address[] calldata admins,
    bool[] calldata flags
  ) external onRep4Migration onlyRole(MIGRATOR_ROLE) {
    if (poolIds.length != admins.length || poolIds.length != flags.length) {
      revert ErrInvalidArguments(msg.sig);
    }

    for (uint256 i; i < poolIds.length; ++i) {
      _poolDetail[poolIds[i]].wasAdmin[admins[i]] = flags[i];
    }

    emit MigrateWasAdminFinished();
  }

  /**
   * @dev Mark the REP-4 migration is finished. Disable the `migrateWasAdmin` method.
   */
  function disableMigrateWasAdmin() external onRep4Migration onlyRole(MIGRATOR_ROLE) {
    assembly {
      sstore($_StakingRep4MigratedStorageLocation, 0x01)
    }

    emit MigrateWasAdminDisabled();
  }

  /**
   * @inheritdoc IStaking
   */
  function execRecordRewards(
    address[] calldata poolIds,
    uint256[] calldata rewards,
    uint256 period
  ) external payable override onlyContract(ContractType.VALIDATOR) {
    _recordRewards(poolIds, rewards, period);
  }

  /**
   * @inheritdoc IStaking
   */
  function execDeductStakingAmount(
    address poolId,
    uint256 amount
  ) external override onlyContract(ContractType.VALIDATOR) returns (uint256 actualDeductingAmount_) {
    actualDeductingAmount_ = _deductStakingAmount(_poolDetail[poolId], amount);
    address payable validatorContractAddr = payable(msg.sender);
    if (!_unsafeSendRON(validatorContractAddr, actualDeductingAmount_)) {
      emit StakingAmountDeductFailed(poolId, validatorContractAddr, actualDeductingAmount_, address(this).balance);
    }
  }

  /**
   * @inheritdoc RewardCalculation
   */
  function _currentPeriod() internal view virtual override returns (uint256) {
    return IRoninValidatorSet(getContract(ContractType.VALIDATOR)).currentPeriod();
  }

  /**
   * @inheritdoc CandidateStaking
   */
  function _deductStakingAmount(
    PoolDetail storage _pool,
    uint256 amount
  ) internal override returns (uint256 actualDeductingAmount_) {
    actualDeductingAmount_ = Math.min(_pool.stakingAmount, amount);

    _pool.stakingAmount -= actualDeductingAmount_;
    _changeDelegatingAmount(
      _pool,
      _pool.__shadowedPoolAdmin,
      _pool.stakingAmount,
      Math.subNonNegative(_pool.stakingTotal, actualDeductingAmount_)
    );
    emit Unstaked(_pool.pid, actualDeductingAmount_);
  }
}

